static int passed=0;
static void require(bool condition,const char*message){if(!condition)throw std::runtime_error(message);}
static void pass(const char*name){std::cout<<"PASS "<<name<<"\n";passed++;}
static void configure(Engine&e){e.eventParameter(Volume,1);e.eventParameter(Mix,0);e.eventParameter(ToneI,13);e.eventParameter(Variation,0);e.eventParameter(AfterVCO,0);e.eventParameter(AfterVCF,0);for(int b=0;b<2;b++){for(int p=0;p<PatchCount;p++)e.eventParameter(panel(b,p),0);e.eventParameter(panel(b,PW),.5);e.eventParameter(panel(b,Sine),1);e.eventParameter(panel(b,AmpSustain),1);e.eventParameter(panel(b,AmpLevel),1);}e.reset();}
static std::vector<float>render(Engine&e,int count,float ext=0){std::vector<float>l(count),r(count),x(count,ext);e.process(l.data(),r.data(),count,x.data());for(float v:l)require(std::isfinite(v)&&std::abs(v)<20,"nonfinite or excessive sample");return l;}
static double rms(const std::vector<float>&a,size_t start=0){double energy=0;for(size_t i=start;i<a.size();i++)energy+=a[i]*a[i];return std::sqrt(energy/std::max(size_t(1),a.size()-start));}
static double difference(const std::vector<float>&a,const std::vector<float>&b){double sum=0;for(size_t i=0;i<a.size();i++)sum+=std::abs(a[i]-b[i]);return sum/a.size();}
static CS80AudioUnit*makeAU(double rate=48000,int channels=2){NSError*error=nil;AudioComponentDescription d={kAudioUnitType_MusicDevice,'Cs80','DjAz',0,0};CS80AudioUnit*u=[[CS80AudioUnit alloc]initWithComponentDescription:d options:0 error:&error];require(u!=nil,"AU construction failed");AVAudioFormat*f=[[AVAudioFormat alloc]initStandardFormatWithSampleRate:rate channels:channels];require([u.outputBusses[0]setFormat:f error:&error],"format rejected");require([u.inputBusses[0]setFormat:f error:&error],"input format rejected");require([u allocateRenderResourcesAndReturnError:&error],"AU resource allocation failed");return u;}
static void writeWav(const char*path,const std::vector<float>&l,const std::vector<float>&r,int rate){std::ofstream f(path,std::ios::binary);auto u16=[&](uint16_t x){f.put(x&255);f.put(x>>8);};auto u32=[&](uint32_t x){u16(x&65535);u16(x>>16);};f.write("RIFF",4);u32(uint32_t(l.size()*4+36));f.write("WAVEfmt ",8);u32(16);u16(1);u16(2);u32(rate);u32(rate*4);u16(4);u16(16);f.write("data",4);u32(uint32_t(l.size()*4));for(size_t i=0;i<l.size();i++){u16(int16_t(std::clamp(l[i],-1.f,1.f)*32767));u16(int16_t(std::clamp(r[i],-1.f,1.f)*32767));}require(bool(f),"WAV output failed");}
static int standaloneProbe(){
 [NSApplication sharedApplication];AudioComponentDescription d={kAudioUnitType_MusicDevice,'Cs8T','DjAz',0,0};
 [AUAudioUnit registerSubclass:CS80AudioUnit.class asComponentDescription:d name:@"CS80 Test: Local Bridge" version:0x00010400];
 __block AVAudioUnit*instrument=nil;__block BOOL opened=NO;
 [AVAudioUnit instantiateWithComponentDescription:d options:0 completionHandler:^(AVAudioUnit*u,NSError*error){instrument=u;opened=YES;}];
 NSDate*deadline=[NSDate dateWithTimeIntervalSinceNow:10];while(!opened&&deadline.timeIntervalSinceNow>0)[NSRunLoop.currentRunLoop runMode:NSDefaultRunLoopMode beforeDate:[NSDate dateWithTimeIntervalSinceNow:.05]];
 require(opened&&instrument,"standalone in-process host did not instantiate");AUAudioUnit*u=instrument.AUAudioUnit;
 std::cout<<"Standalone host exposes "<<NSStringFromClass(u.class).UTF8String<<"\n";
 require(u.factoryPresets.count==11+PerformancePresetCount,"standalone host did not expose cinematic presets");
 u.currentPreset=u.factoryPresets[11];require([u.parameterTree parameterWithAddress:ToneI].value==13,"standard host API did not apply performance preset");require(u.currentPreset.number==11,"standalone preset identity failed");
 std::cout<<"PASS standalone bridge loads performance presets through the public Audio Unit API\n";return 0;
}
static int hostProbe(){
 [NSApplication sharedApplication];__block AVAudioUnit*instrument=nil;__block NSError*failure=nil;__block BOOL opened=NO;
 AudioComponentDescription d={kAudioUnitType_MusicDevice,'Cs80','DjAz',0,0};
 [AVAudioUnit instantiateWithComponentDescription:d options:kAudioComponentInstantiation_LoadOutOfProcess completionHandler:^(AVAudioUnit*u,NSError*error){instrument=u;failure=error;opened=YES;}];
 NSDate*deadline=[NSDate dateWithTimeIntervalSinceNow:20];while(!opened&&deadline.timeIntervalSinceNow>0)[NSRunLoop.currentRunLoop runMode:NSDefaultRunLoopMode beforeDate:[NSDate dateWithTimeIntervalSinceNow:.05]];
 require(opened&&instrument,"registered AUv3 could not instantiate out of process");require(!failure,"AUv3 instantiation returned an error");
 require(instrument.AUAudioUnit.providesUserInterface,"registered extension does not advertise UI");
 __block BOOL viewed=NO;__block NSViewController*controller=nil;
 [instrument.AUAudioUnit requestViewControllerWithCompletionHandler:^(NSViewController*vc){controller=vc;viewed=YES;}];
 deadline=[NSDate dateWithTimeIntervalSinceNow:20];while(!viewed&&deadline.timeIntervalSinceNow>0)[NSRunLoop.currentRunLoop runMode:NSDefaultRunLoopMode beforeDate:[NSDate dateWithTimeIntervalSinceNow:.05]];
 require(viewed&&controller,"AUv3 custom view did not instantiate");
 std::cout<<"PASS registered out-of-process AUv3 and custom host view ("<<NSStringFromClass(controller.class).UTF8String<<")\n";
 AVAudioEngine*engine=[AVAudioEngine new];[engine attachNode:instrument];AVAudioFormat*format=[[AVAudioFormat alloc]initStandardFormatWithSampleRate:48000 channels:2];[engine connect:instrument to:engine.mainMixerNode format:format];NSError*error=nil;
 require([engine enableManualRenderingMode:AVAudioEngineManualRenderingModeOffline format:format maximumFrameCount:512 error:&error],"host offline mode failed");require([engine startAndReturnError:&error],"host engine failed");
 uint8_t note[3]={0x90,60,100};instrument.AUAudioUnit.scheduleMIDIEventBlock(AUEventSampleTimeImmediate,0,3,note);
 AVAudioPCMBuffer*buffer=[[AVAudioPCMBuffer alloc]initWithPCMFormat:format frameCapacity:512];double energy=0;
 for(int j=0;j<12;j++){AVAudioEngineManualRenderingStatus status=[engine renderOffline:512 toBuffer:buffer error:&error];require(status==AVAudioEngineManualRenderingStatusSuccess,"host rendering failed");for(int i=0;i<512;i++)energy+=buffer.floatChannelData[0][i]*buffer.floatChannelData[0][i];}
 [engine stop];require(energy>0,"registered instrument rendered silence");std::cout<<"PASS host-engine MIDI and audio render, energy "<<energy<<"\n";return 0;
}
