 {Engine e;configure(e);require(rms(render(e,1024))==0,"idle unit is not silent");e.midi(0x90,69,100);auto a=render(e,48000);int crossings=0;for(size_t i=12001;i<a.size();i++)if(a[i-1]<=0&&a[i]>0)crossings++;double hz=crossings/.75;require(std::abs(hz-440)<2,"sine tuning error");pass("silence and analytic 440 Hz tuning");}
 {Engine a,b;configure(a);configure(b);a.eventParameter(panel(0,HPF),1);a.eventParameter(panel(0,LPF),0);b.eventParameter(panel(0,HPF),0);b.eventParameter(panel(0,LPF),1);a.midi(0x90,60,100);b.midi(0x90,60,100);require(difference(render(a,12000),render(b,12000))<1e-8,"sine did not bypass filters");pass("sine bypasses HPF and LPF");}
 {Engine e;configure(e);for(int i=0;i<8;i++)e.midi(0x90,60+i,100);e.midi(0x90,90,100);require(e.heldCount()==8,"held note capacity wrong");for(int i=0;i<8;i++)require(e.voice(i).note!=90,"ninth held note stole a voice");e.midi(0x80,90,0);require(e.heldCount()==8,"ignored note-off released a real voice");pass("eight assignments and ignored ninth key");}
 {Engine e;configure(e);for(int i=0;i<8;i++){e.midi(0x90,60,100);require(e.voice(i).held,"round robin did not advance");e.midi(0x80,60,0);}pass("successive strikes rotate across eight voices");}
 {Engine e;configure(e);e.midi(0x90,60,100);e.midi(0x90,64,100);e.midi(0xa0,60,110);require(e.voice(0).pressure>.86&&e.voice(1).pressure==0,"poly pressure affected wrong note");e.midi(0xd0,50,0);require(std::abs(e.voice(0).pressure-50/127.f)<1e-6&&e.voice(1).pressure>0,"channel pressure fallback failed");pass("APC64 polyphonic pressure and channel-pressure fallback");}
 {Engine e;configure(e);e.eventParameter(Sustain,3);e.eventParameter(SustainMode,0);e.midi(0x90,60,100);render(e,1000);e.midi(0x80,60,0);render(e,1000);e.midi(0x90,64,100);require(e.activeCount()==2,"Sustain I discarded a tail");e.eventParameter(SustainMode,1);e.midi(0x90,67,100);require(e.activeCount()==2,"Sustain II did not discard released tail");pass("Sustain I / II phrase-tail behavior");}
 {Engine e;configure(e);e.eventParameter(panel(0,AmpRelease),.5);e.eventParameter(Sustain,5);e.eventParameter(SustainAssign,1);e.midi(0x90,60,100);render(e,1000);e.midi(0x80,60,0);render(e,1000);require(e.activeCount()==1,"unplugged foot switch should act closed");e.midi(0xb0,64,127);e.midi(0xb0,64,0);render(e,2000);require(e.activeCount()==0,"pedal release did not end assigned sustain");pass("unplugged pedal semantics and pedal cancellation");}
 {Engine e;configure(e);e.eventParameter(Glide,10);e.midi(0x90,72,100);render(e,48000);require(std::abs(e.voice(0).key-66)<.02,"glide rate should scale with pitch interval");pass("portamento full-range timing");}
 {Engine e;configure(e);e.eventParameter(panel(0,IL),.7);e.eventParameter(panel(0,AL),.8);e.midi(0x90,60,100);render(e,2000);require(std::abs(e.voice(0).layers[0].filter.value)<.001,"filter envelope did not settle at reference");e.midi(0x80,60,0);render(e,400);require(e.voice(0).layers[0].filter.value<-.5,"filter release did not return toward IL");pass("IL / AL filter-envelope reference and release");}
 {Engine e;configure(e);e.eventParameter(SubFunction,5);e.eventParameter(SubVCA,1);e.midi(0x90,69,100);auto low=render(e,12000,-1);auto high=render(e,12000,1);require(rms(high,2000)>rms(low,2000)*5,"external modulation bus had no effect");pass("external signal modulates voice amplitude");}
 {Engine e;configure(e);e.midi(0x90,69,100);render(e,2000);e.eventParameter(Volume,0,100);auto a=render(e,150);require(rms(a,120)<rms(a)*.01,"parameter ramp did not reach target");pass("parameter ramp completes across render state");}
 {for(double sr:{44100.,48000.,96000.}){Engine e;configure(e);e.prepare(sr);e.midi(0x90,60,100);require(rms(render(e,int(sr*.2)))>.001,"silence at supported sample rate");e.midi(0x90,64,0);e.midi(0xb0,120,0);render(e,1000);require(e.activeCount()==0,"panic left active voices");}pass("44.1 / 48 / 96 kHz and all-sound-off");}
