 {Engine a,b;configure(a);configure(b);for(Engine*e:{&a,&b}){e->eventParameter(ToneII,13);e->eventParameter(Mix,1);e->eventParameter(panel(1,Sine),1);e->eventParameter(panel(1,AmpSustain),1);e->eventParameter(panel(1,AmpLevel),1);}a.eventParameter(panel(0,LPF),0);b.eventParameter(panel(0,LPF),1);a.midi(0x90,60,100);b.midi(0x90,60,100);require(difference(render(a,12000),render(b,12000))<1e-8,"channel I filter changed channel II audio");pass("channel filters remain independent across the two banks");}
