 {Engine a,b;configure(a);configure(b);a.eventParameter(Glide,10);b.eventParameter(Glide,10);b.eventParameter(Glissando,1);a.midi(0x90,72,100);b.midi(0x90,72,100);require(difference(render(a,9000),render(b,9000))>.001,"glissando did not differ from continuous glide");pass("glissando quantizes the continuous glide path");}
 {Engine e;configure(e);e.midi(0xb0,16,127);require(e.get(Brilliance)==1,"APC custom brilliance CC failed");e.midi(0xb0,22,127);require(e.get(RingSpeed)==2000,"APC custom ring-rate CC failed");e.midi(0x90,255,100);require(e.heldCount()==0,"malformed MIDI data was not ignored");pass("APC64 custom fader mappings and malformed MIDI guard");}
 // Isolate controller/pedal discontinuities from the oscillator spectrum.
 {double worst=0;for(double sr:{44100.,48000.,96000.})for(int mode=0;mode<3;mode++){Engine e;configure(e);e.prepare(sr);e.eventParameter(panel(0,AfterLevel),1);e.eventParameter(panel(0,AmpRelease),1);if(mode==2){e.eventParameter(Sustain,5);e.eventParameter(SustainAssign,1);}e.midi(0x90,48,100);auto before=render(e,int(sr*.125));if(mode==2){e.midi(0x80,48,0);before=render(e,int(sr*.125));}if(mode==0)e.midi(0xa0,48,127);if(mode==1)e.midi(0xb0,11,0);if(mode==2)e.midi(0xb0,64,0);auto after=render(e,int(sr*.07));std::vector<float>a={before[before.size()-2],before.back()};a.insert(a.end(),after.begin(),after.end());double peak=0;for(size_t i=2;i<a.size();i++)peak=std::max(peak,std::abs(double(a[i]-2*a[i-1]+a[i-2])));worst=std::max(worst,peak);require(peak<.0015,"pressure, expression or pedal cancellation introduces a discontinuity");if(mode==0)require(e.voice(0).smoothPressure>.999,"pressure smoothing never reaches its target");if(mode==1)require(rms(render(e,int(sr*.5)),int(sr*.45))<1e-6,"MIDI expression does not reach silence after DC-blocker settling");if(mode==2)require(e.activeCount()==0,"pedal cancellation leaves a voice active");}std::cout<<"Controller/pedal peak second difference: "<<worst<<"\n";pass("pressure, MIDI expression and pedal cancellation remain continuous at three sample rates");}
 {auto timeline=[](int block){Engine e;auto sound=performancePreset(0);for(int a=0;a<ParameterCount;a++)e.eventParameter(a,sound.values[a]);e.reset();std::vector<float>l(96000),r(l.size());for(int pos=0;pos<96000;){if(pos==0)for(int n:{48,55,60})e.midi(0x90,n,100);if(pos==24000)e.midi(0xa0,60,127);if(pos==36000)e.midi(0xa0,60,0);if(pos==48000)e.midi(0xb0,11,64);if(pos==60000)for(int n:{48,55,60})e.midi(0x80,n,0);int boundary=(pos/12000+1)*12000;int n=std::min({block,boundary-pos,96000-pos});e.process(l.data()+pos,r.data()+pos,n);pos+=n;}for(float x:l)require(std::isfinite(x)&&std::abs(x)<1,"Horizon Brass controller sequence clips or becomes nonfinite");return l;};auto a=timeline(512);require(difference(a,timeline(17))<1e-8,"Horizon Brass modulation changes with host buffer size");require(rms(a,24000)>.001,"Horizon Brass sequence is silent");writeWav("output/audio/horizon-brass-controller-check.wav",a,a,48000);pass("Horizon Brass pressure/expression/release sequence is finite, unclipped and buffer independent");}
