 {Engine e;configure(e);e.eventParameter(SustainMode,1);e.eventParameter(Sustain,5);e.midi(0x90,48,100);auto before=render(e,1000);e.midi(0x80,48,0);auto tail=render(e,240);e.midi(0x90,55,100);auto next=render(e,160);std::vector<float>a={tail[tail.size()-2],tail.back()};a.insert(a.end(),next.begin(),next.end());double spike=0;for(size_t i=2;i<a.size();i++)spike=std::max(spike,std::abs(double(a[i]-2*a[i-1]+a[i-2])));std::cout<<"Sustain-II onset peak second difference: "<<spike<<"\n";require(spike<.002,"Sustain II truncates a tail with a click");pass("Sustain II changes phrases without a hard tail cut");}
