 {double peak=0;for(int tone=0;tone<11;tone++){Engine e;e.eventParameter(ToneI,tone);e.eventParameter(ToneII,tone);e.eventParameter(Volume,1);for(int n:{48,52,55,59,60,64,67,71})e.midi(0x90,n,127);auto a=render(e,24000);for(float x:a)peak=std::max(peak,std::abs(double(x)));}require(peak<1,"factory eight-note chords clip at the default output calibration");std::cout<<"Factory-chord peak at full master volume: "<<peak<<"\n";pass("factory fast-attack chords retain digital headroom");}
