 {CS80AudioUnit*u=makeAU();require(u.parameterTree.allParameters.count==ParameterCount,"AU parameter tree incomplete");[u.parameterTree parameterWithAddress:memory(3,LPF)].value=.123;[u.parameterTree parameterWithAddress:Detune].value=-17;NSDictionary*state=u.fullState;[u.parameterTree parameterWithAddress:Detune].value=23;u.fullState=state;require(std::abs([u.parameterTree parameterWithAddress:Detune].value+17)<1e-5,"AU state did not recall global");require(std::abs([u.parameterTree parameterWithAddress:memory(3,LPF)].value-.123)<1e-5,"AU state did not recall memory");[u deallocateRenderResources];pass("AU parameter tree and complete host state round trip");}
